"""Original Tallyspring woman, spring-disc launcher grips and action guides."""
import json
from PIL import Image
import produce as p
UID='unit_brasshollow_tallyspring_throwers'
B=p.ROOT/'art/animation/source/poses'/UID
IDENTITY=('Original TALLYSPRING THROWER woman from supplied painting, fixed three-quarter camera facing SCREEN RIGHT. One sturdy young adult human woman with reddish brown hair tied into a messy bun, red cloth headband, focused face, rusty red sleeves and trousers, dark weathered leather apron, brown belt with three small brass tally tags and a cylindrical pouch, one riveted steel shoulder plate, steel forearm bracers and brown leather boots with brass toe caps and straps. Exactly TWO arms, TWO hands, TWO legs. ONE original short rectangular brass-framed spring-disc launcher: a dark black horizontal exposed coil between brass rails, square open muzzle on SCREEN RIGHT, top open box holding round brass tally discs. No long gun barrel, crossbow, staff or additional weapon. Anatomical RIGHT near hand holds the rear trigger grip, anatomical LEFT far hand supports the forward underside of the same launcher. Both grips remain attached except the explicitly described reload or death. Preserve launcher shape, spring coil, loaded disc box, apron, tags, shoulder plate and original face throughout. Original painterly tactical game artwork, no live action or plastic material. ')
PLATE=(' Entire backdrop stays uniform magenta RGB255,0,255. No floor, cast shadow, scenery, text, camera motion, cuts or zoom. Fixed ground plane y576, body anchored at x480. Lifted feet may move but planted contacts cannot slide. Keep launcher, hands and all boots inside generous canvas margins. No projectiles, sparks, particles, muzzle flash, smoke, rings, beams, glow or new equipment. ')
def reference(index):
 f=dict(json.loads((B/'packing.json').read_bytes())['frames'][index]);f['source']=(B/f['source']).relative_to(p.ROOT).as_posix();f['alpha_noise_cutoff']=8;return f
def recipe(clip,indices,guides,last,action,seed):
 out=p.SOURCE_DIR/(clip+'_h3_v1');out.mkdir(exist_ok=False)
 c=dict(unit_id=UID,clip=clip,canvas=[960,640],anchor=[480,576],scale=.5,key_rgb=[255,0,255],seed=seed,references=[reference(i) for i in indices],guides=guides,last=last,prompt=(IDENTITY+action+PLATE).strip(),tiled_decode=dict(tile_size=512,overlap=64,temporal_size=16,temporal_overlap=4))
 p.write(out/'config.json',c);p.prepare(out,c);p.verify(out,c);print('Prepared',clip,flush=True)
if __name__=='__main__':
 recipe('move',[18,2,3,4,5],[[24,1],[44,2],[70,3],[93,4]],0,'One complete reciprocal walking cycle IN PLACE. Near RIGHT leg extends and plants while far LEFT leg trails, far leg passes and extends, near leg lifts and passes, then return to original ready. Hips, knees and boot ankles articulate. Apron and tally tags respond subtly. Launcher stays lowered in both original hands. Opposite planted support and two distinct legs, no sliding or root travel. ',2026110201)
 recipe('attack',[18,6,7],[[26,1],[53,2],[88,1]],0,'One short physical melee shove using the held launcher body. Both hands pull the launcher across chest, bend knees, then thrust the same launcher muzzle SCREEN RIGHT once toward adjacent contact without firing. Recover continuously through the drawn-back stance to original lowered ready. Exactly one thrust and one recovery, no repeated attack or late re-aim. ',2026110202)
 recipe('ranged',[18,11,12,13],[[29,1],[58,2],[88,3]],0,'One ranged spring-disc release and reload. Raise launcher and sight SCREEN RIGHT, keep RIGHT hand on trigger and LEFT beneath the front. Squeeze the trigger once around frame45, visible small shoulder and arm recoil as spring relaxes. There is NO visible disc projectile or muzzle flash because the game owns those effects. After recoil, RIGHT hand briefly moves to the rear winding crank and pulls it once while LEFT hand holds the launcher, then RIGHT hand restores its trigger grip and both arms lower to original ready. Preserve both hands and launcher dimensions through reload. ',2026110203)
 recipe('hit',[18,10],[[39,1]],0,'One impact recoil: chest and head recoil backward, knees flex and both original hands retain launcher; boots stay grounded. Recover continuously to original upright ready. No firing, falling, attack or repeated recoil. ',2026110204)
 recipe('defend',[18,8],[],1,'One dedicated defensive brace transition. Bend knees, lower torso and settle one knee onto ground as in original guard painting. Draw launcher horizontally across chest with both hands, head ducks behind the same held body. End in compact original kneeling guard and hold final second. No aim, release or attack. ',2026110205)
 recipe('cast',[18],[],0,'One NONMAGICAL physical rally salute. Both boots stay planted and both original hands keep their launcher grips. Lift the held launcher deliberately diagonally above the shoulder, so its square muzzle points thirty degrees above SCREEN RIGHT, with visibly raised elbows, torso lifting and one clear head nod. Hold the high salute briefly, then lower continuously to original ready. Mouth stays clear, no sighting or firing, no spellcasting or extra arm. ',2026110206)
 recipe('death',[18,14,15,17],[[34,1],[68,2]],3,'One continuous forward-to-side grounded collapse. Knees buckle, torso lowers onto knees, then tips forward onto hands and falls coherently onto original side. Both hands release the same launcher as body loses support; launcher settles in front of the fallen body. Preserve exactly two arms and two legs and original boot sizes throughout. Hair bun, headband, shoulder plate, apron and launcher remain recognizable. Finish in original prone corpse guide with eyes closed and all body/equipment grounded y576, final second completely still. ',2026110207)
 p.write(p.SOURCE_DIR/'delivery.json',dict(takes=[c+'_h3_v1' for c in ['move','attack','ranged','hit','defend','cast','death']],preserved_accepted_clips=['idle'],visual_review=dict(status='pending',notes='Original woman,26 source poses and8 idle hands phases personally inspected. Preserve accepted idle/map pixels and240ms timing; seven dedicated H3 actions still require complete original RGB/RGBA, enlarged, native/reflected and runtime visual acceptance.')))
 p.write(p.SOURCE_DIR/'runtime_registration.json',dict(unit_id=UID,reference_height=256,canvas=[960,640],ground_anchor=[480,576],output_scale=.5,ready_guide=reference(18),corpse_guide=reference(17),reason='One original scale per painting divided by fixed extraction scale; fixed anatomical contact plane, no per-frame normalization.'))
